def label(s,color=MAROON):return f'<p style="margin:0 0 12px;color:{color};font:700 10px/16px Arial,sans-serif;letter-spacing:2px;text-transform:uppercase;">{s}</p>'
def title(s,size=36,color=INK):return f'<h2 class="headline" style="margin:0 0 14px;color:{color};font:700 {size}px/{size+2}px Georgia,serif;letter-spacing:-1.2px;">{s}</h2>'
